 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.a_13_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods60401.a_13_onclick' }); }
};

