/**
 * @event
 * @name scwin.grd_inqDiscls_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_inqDiscls_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_inqDiscls');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_inqDiscls'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; } /* 수동 전환 필요: updateInqDiscls (조건 미해석) */
        if (r["procsCompltYn"] !== 'Y') { if (typeof scwin.goWrite === 'function') { scwin.goWrite(r["reqFormCd"], r["reqFormVer"], r["acptNo"]); } else { console.error('[sdd] 행 동작 미정의: scwin.goWrite (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.goWrite'); } return; }
        if (typeof scwin.goViewer === 'function') { scwin.goViewer(r["acptNoAns"]); } else { console.error('[sdd] 행 동작 미정의: scwin.goViewer (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.goViewer'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_inqDiscls.oncellclick' });
    }
};

/**
 * @event
 * @name scwin.grd_explDiscls_oncellclick
