 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_explDiscls_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_explDiscls');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_explDiscls'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; } /* 수동 전환 필요: updateExplDiscls (조건 미해석) */
        if (columnId === "__rowAct") { if (typeof scwin.goViewer === 'function') { scwin.goViewer(r["acptNo"]); } else { console.error('[sdd] 행 동작 미정의: scwin.goViewer (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.goViewer'); } return; } if (typeof scwin.updateExplDiscls === 'function') { scwin.updateExplDiscls(r["orgAcptNo"], r["count"]); } else { console.error('[sdd] 행 동작 미정의: scwin.updateExplDiscls (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.updateExplDiscls'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_explDiscls.oncellclick' });
    }
};

/**
