    try {
        const dl = $c.util.getComponent("dlt_inqDiscls");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "count") ?? '') : '');
        if (Number(v) === 1) { return "class=\"bgcolor1\""; }
