/**
 * @event
 * @name scwin.grd_explDiscls_fillAct
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.grd_explDiscls_fillAct = async function () {
    try {
        const dl = $c.util.getComponent('dlt_explDiscls');
        if (!dl || !dl.getTotalRow) { return; }
        for (let i = 0; i < dl.getTotalRow(); i++) {
            const r = dl.getRowJSON(i);
            const v = '-';
            if (r) {  }
            dl.setCellData(i, "__rowAct", v);
        }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_explDiscls.fillAct' });
    }
};

