/**
 * @method
 * @name scwin.numberFormat
 * @author Inswave
 * @date 2026. 09. 29
 * @param numstr ret
 * @returns
 * @hidden N
*/
scwin.numberFormat = function (numstr, ret) {
    /* sdd-asis-lifecycle:begin fn_NumberFormat — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (numstr != null && numstr !== '') {
        numstr = scwin.setComma(scwin.delComma(numstr));
        if (ret) {
            ret.value = numstr;
        }
        return numstr;
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.setComma
 * @author Inswave
 * @date 2026. 09. 29
 * @param numstr
 * @returns
 * @hidden N
*/
scwin.setComma = function (numstr) {
    /* sdd-asis-lifecycle:begin fn_SetComma — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    numstr = String(numstr);
    const re0 = /^(-?\d+)(\d{3})($|\..*$)/;
    if (re0.test(numstr)) {
        return numstr.replace(re0, function(str, p1, p2, p3) {
                return scwin.setComma(p1) + ',' + p2 + p3;
        });
    } else {
        return numstr;
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.delComma
 * @author Inswave
 * @date 2026. 09. 29
 * @param numstr
 * @returns
 * @hidden N
*/
scwin.delComma = function (numstr) {
    /* sdd-asis-lifecycle:begin fn_DelComma — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    numstr = String(numstr);
    if (numstr === '') {
        return '';
    } else {
        if (numstr === '0-') {
            return '';
        }
    }
    numstr = numstr.replace(/[^\d\.-]/g, '');
    numstr = String(numstr.match(/^-?\d*\.?\d*/));
    numstr = numstr.replace(/^(-?)(\d*)(.*)/, function(str, p1, p2, p3) {
            p2 = (p2 > 0) ? String(p2.match(/[1-9]\d*$/)) : '0';
            return p1 + p2 + p3;
    });
    return numstr;
    /* sdd-asis-lifecycle:end */
};


